    chat: { providers: () => Promise<TextProviderConfig[]>; selectAttachments: () => Promise<Array<{ name: string; content: string }>>; start: (requestId: string, conversationId: number, prompt: string, provider: string) => Promise<{ userMessage: RainbowMessage; assistantMessage: RainbowMessage }>; stop: (requestId: string) => Promise<boolean>; onDelta: (callback: (payload: ChatEvent) => void) => () => void; onDone: (callback: (payload: ChatEvent) => void) => () => void; onError: (callback: (payload: ChatEvent) => void) => () => void }
