    works: { listText: () => Promise<TextWork[]>; saveText: (title: string, content: string, conversationId?: number) => Promise<TextWork>; list: () => Promise<UnifiedWork[]>; page: (input: WorksPageInput) => Promise<WorksPageResult>; byKeys: (keys: string[]) => Promise<UnifiedWork[]>; preview: (type: WorkType, id: number) => Promise<UnifiedWork | null>; update: (type: WorkType, id: number, input: { title: string; favorite: boolean; tags: string }) => Promise<boolean>; delete: (type: WorkType, id: number) => Promise<boolean>; exportText: (id: number, title: string, content: string) => Promise<boolean>; openLocation: (path: string) => Promise<boolean>; downloadFile: (path: string, title: string) => Promise<boolean>; addProject: (type: WorkType, id: number, projectId: number) => Promise<boolean>; createTask: (type: WorkType, id: number, projectId: number, title: string) => Promise<RainbowTask>; backup: () => Promise<string | null> }
    image: { providers: () => Promise<ImageProviderConfig[]>; selectReference: () => Promise<{ path: string; name: string; data_url: string } | null>; generate: (requestId: string, provider: string, input: ImageGenerationInput) => Promise<ImageWork[]>; stop: (requestId: string) => Promise<boolean>; works: () => Promise<ImageWork[]>; download: (id: number) => Promise<boolean> }
    publishing: { accounts: { list: () => Promise<PublishAccount[]>; create: (input: PublishAccountInput) => Promise<PublishAccount>; update: (id: number, input: PublishAccountInput & { enabled: boolean }) => Promise<PublishAccount>; delete: (id: number) => Promise<boolean>; test: (id: number) => Promise<{ ok: boolean; message: string }>; authorizeBrowser: (id: number, browser: 'edge' | 'chrome') => Promise<unknown>; importCookies: (id: number) => Promise<unknown>; clearAuthorization: (id: number) => Promise<unknown>; openLogin: (id: number) => Promise<{ ok: boolean; url: string }> }; list: () => Promise<Publication[]>; create: (input: PublicationInput) => Promise<Publication[]>; update: (id: number, input: PublicationUpdateInput) => Promise<Publication>; validate: (id: number) => Promise<PublicationValidation>; run: (id: number) => Promise<Publication>; cancel: (id: number) => Promise<Publication>; retry: (id: number) => Promise<Publication>; complete: (id: number) => Promise<Publication>; fail: (id: number) => Promise<Publication>; copy: (id: number) => Promise<Publication>; delete: (id: number) => Promise<boolean>; onUpdated: (callback: (id: number) => void) => () => void }
